a11y.gameScreen.countingArea.accessibleP.value:
{ $type ->
  [kittens] ស្តាំ now, { $leftAddend } ពណ៌លឿង កូនឆ្មា, { $rightAddend } ពណ៌ខៀវ កូនឆ្មា in Counting Area.
  *[numberLine] { $visible ->
                  [none] { a11y_gameScreen_countingArea_numberLineSentence }
                  [addends] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineAddends }
                  [tickMarks] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineTickMarks }
                  *[both] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineAddends } { a11y_gameScreen_countingArea_numberLineTickMarks }
                }
}

